/// Every colour role in the design system.
enum ItColorToken: String, CaseIterable {
    /// App background and sidebar. Neutral with a faint green bias.
    case page = "page"
    /// Working surface: main content, sheets, phone screens. Always opaque outdoors.
    case surface = "surface"
    /// Portrait discs and quiet fills inside rows. Never a card background.
    case sunk = "sunk"
    /// Current nav item and the highlighted employee row when a hexagon side is selected.
    case selected = "selected"
    /// Hairlines (1 px) between rows and sections, and the six resting spokes. Decorative: never the only carrier of meaning.
    case line = "line"
    /// Primary text. 17.3:1 on surface (light), 14.5:1 (dark). Also highlighted spokes.
    case text = "text"
    /// Metadata, secondary text, idle and unavailable states. 6.3:1 on surface (light), 7.5:1 (dark).
    case meta = "meta"
    /// GENERATED per tenant from tenant.config.json brand input (example tenant shown: Mowology, input #2D8659, pinned #1B5F3C). Exactly one role: the dominant action 
    case tenant = "tenant"
    /// GENERATED with tenant. Label on a filled tenant button.
    case onTenant = "on-tenant"
    /// Ittai indigo. Brand moments only: wordmark, symbol, sign-in, marketing. Never inside working screens.
    case brand = "brand"
    /// Knowledge brain only. Discovered triangle outline; never an operational status colour.
    case knowledgeDiscovered = "knowledge-discovered"
    /// Knowledge brain only. Understood triangle fill; never an operational status colour.
    case knowledgeUnderstood = "knowledge-understood"
    /// Knowledge brain only. Mastered triangle fill with an inner page-colour keyline; never an operational status colour.
    case knowledgeMastered = "knowledge-mastered"
    /// Work status: complete. Paired with the solid check icon.
    case statusComplete = "status-complete"
    /// Work status: needs attention. Paired with the triangle icon. 6.5:1 (light), 7.9:1 (dark).
    case statusAttention = "status-attention"
    /// Work status: blocked or failed. Paired with the sharp-cornered octagon. 7.3:1 (light), 6.9:1 (dark).
    case statusBlocked = "status-blocked"
    /// Work status: in progress. Paired with the clock icon. Also the focus ring.
    case statusProgress = "status-progress"
    /// AI employee state Working: solid side or ring + clock icon + the word.
    case stateWorking = "state-working"
    /// AI employee state Waiting for approval: solid side or ring + triangle + the word.
    case stateApproval = "state-approval"
    /// AI employee state Blocked: solid side or ring + octagon + the word.
    case stateBlocked = "state-blocked"
    /// AI employee state Idle: dotted side or dashed ring + dashed-circle icon + the word.
    case stateIdle = "state-idle"
    /// AI employee state Unavailable: side drops to 1 px + slashed-circle icon + the word.
    case stateUnavailable = "state-unavailable"
    /// 2 px keyboard focus ring, 2 px offset. 6.8:1 on surface (light), 7.8:1 (dark). Field: #24507A.
    case focus = "focus"
    /// GENERATED. The tenant's brand as given, darkened only if needed to reach 3:1 on surface. Tenant logo/monogram tint only.
    case tenantMark = "tenant-mark"
    /// GENERATED. Selected/current tint for tenant-owned marks; text on it ≥7:1.
    case tenantSoft = "tenant-soft"
    /// Sync: saved on this device, not yet sent (cloud icon + 'Saved on phone'). Also offline approvals: 'Approval saved on phone · pending'.
    case syncSaved = "sync-saved"
    /// Sync: sending to the server (cloud-up + 'Sending…').
    case syncSending = "sync-sending"
    /// Sync: the SERVER confirmed (cloud-check + 'Sent 9:14'). Never shown before confirmation.
    case syncSent = "sync-sent"
    /// Sync: couldn't send (cloud-x + reason + Retry).
    case syncFailed = "sync-failed"
    /// Sync: changed elsewhere or no longer valid (cloud-alert + 'Not sent: no longer needed' / 'Review').
    case syncConflict = "sync-conflict"
}

